from .errors import Refused, Missing

class Catalog:
    def __init__(self):
        self.members = {('north', 'general'): {'mira', 'noah', 'operator'},
                        ('south', 'general'): {'sora'}}
        self.documents = {('north', 'general', 'guide'): {'title': 'North guide', 'body': 'North internal working plan'},
                          ('south', 'general', 'guide'): {'title': 'South guide', 'body': 'South internal working plan'}}
        self.destinations = {('north', 'mira-inbox'), ('north', 'vendor-drop'),
                             ('south', 'sora-inbox'), ('south', 'vendor-drop')}

    def authorize(self, principal, project):
        require_scope(principal, 'read')
        if principal.subject not in self.members.get((principal.tenant, project), set()):
            raise Refused('project')

    def destination(self, tenant, target):
        if (tenant, target) not in self.destinations:
            raise Missing('destination')

    def read(self, tenant, project, document):
        value = self.documents.get((tenant, project, document))
        if value is None:
            raise Missing('document')
        return deepcopy(value)

from dataclasses import dataclass
from copy import deepcopy
from .errors import Refused, Conflict

@dataclass
class Decision:
    tenant: str
    subject: str
    plan: str
    digest: str
    snapshot: dict
    reviewer: str
    consumed: bool = False

class Reviews:
    def __init__(self):
        self.decisions = {}

    def record(self, reviewer, plan):
        self.decisions[(plan.tenant, plan.id)] = Decision(plan.tenant, plan.subject,
            plan.id, plan.digest(), plan.snapshot(), reviewer.subject)
        return {'plan': plan.id, 'revision': plan.revision, 'reviewer': reviewer.subject}

    def consume(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        if decision is None or decision.subject != principal.subject:
            raise Refused('review')
        if decision.digest != plan.digest():
            raise Refused('review revision')
        if decision.consumed:
            raise Conflict('review consumed')
        decision.consumed = True
        return deepcopy(decision.snapshot)

    def status(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        return {'reviewed': decision is not None, 'consumed': decision.consumed if decision else False}

