class Host:
    def __init__(self, registry, catalog, settings, clock):
        self.registry = registry
        self.settings = settings.validate()
        self.sessions = Sessions(registry.credentials, settings, clock)
        self.discovery = Discovery(registry, catalog)
        self.journal = Journal(settings.journal_capacity)
        self.closed = False

    def open(self, token):
        if self.closed:
            raise Invalid('host closed')
        return self.sessions.open(token)

    def tools(self, sid):
        self.sessions.resolve(sid)
        return self.discovery.list_tools()

    def invoke(self, sid, value):
        if self.closed:
            raise Invalid('host closed')
        session, principal = self.sessions.resolve(sid)
        packet = Packet.parse(value)
        try:
            result = self.registry.call(packet.tool, session.token, packet.arguments, packet.id)
            reply = success(packet.id, result)
        except Exception as error:
            reply = failure(packet.id, error)
        self.journal.append(principal, packet, 'complete' if reply['ok'] else 'failed')
        return reply

    def batch(self, sid, values):
        self.sessions.resolve(sid)
        if not isinstance(values, list) or not 1 <= len(values) <= self.settings.batch_size:
            raise Invalid('batch')
        replies = []
        for value in values:
            replies.append(self.invoke(sid, value))
        return {'replies': replies}

    def history(self, sid, after=0, limit=16):
        _, principal = self.sessions.resolve(sid)
        require_scope(principal, 'read')
        return self.journal.page(principal, integer(after), integer(limit, 1, 64))

    def close_session(self, sid):
        return self.sessions.close(sid)

    def shutdown(self):
        self.closed = True
        self.sessions.rows.clear()

from collections import OrderedDict
from dataclasses import dataclass
from secrets import token_urlsafe
from .errors import Refused, Conflict

@dataclass(frozen=True)
class Session:
    id: str
    token: str
    subject: str
    tenant: str
    credential_id: str
    expires: float

class Sessions:
    def __init__(self, credentials, settings, clock):
        self.credentials = credentials
        self.settings = settings
        self.clock = clock
        self.rows = OrderedDict()

    def prune(self):
        now = self.clock.now()
        for sid, session in list(self.rows.items()):
            if session.expires <= now:
                del self.rows[sid]

    def open(self, token):
        principal = self.credentials.authenticate(token)
        self.prune()
        if len(self.rows) >= self.settings.session_capacity:
            raise Conflict('session capacity')
        sid = token_urlsafe(24)
        session = Session(sid, token, principal.subject, principal.tenant,
                          principal.credential_id, self.clock.now() + self.settings.session_ttl)
        self.rows[sid] = session
        return {'session': sid, 'expires_in': self.settings.session_ttl}

    def resolve(self, sid):
        self.prune()
        if not isinstance(sid, str):
            raise Refused('session')
        session = self.rows.get(sid)
        if session is None:
            raise Refused('session')
        principal = self.credentials.authenticate(session.token)
        if (principal.subject, principal.tenant, principal.credential_id) != (
                session.subject, session.tenant, session.credential_id):
            raise Refused('session identity')
        return session, principal

    def close(self, sid):
        session, _ = self.resolve(sid)
        del self.rows[session.id]
        return {'closed': True}

    def count(self):
        self.prune()
        return len(self.rows)

